const lockUserOwnedOrgs = `-- name: LockUserOwnedOrgs :many
SELECT m.org_id, m.user_id FROM membership m
WHERE m.role = 'owner' AND m.org_id IN (SELECT o.org_id FROM membership o WHERE o.user_id = $1 AND o.role = 'owner')
ORDER BY m.org_id, m.user_id FOR UPDATE OF m
`

type LockUserOwnedOrgsRow struct {
	OrgID  uuid.UUID
	UserID uuid.UUID
}

// Owners of every organization the user owns, locked in (org_id, user_id) order.
// ponytail: reads other orgs inside the caller's InOrg tx; stage 42 RLS must allow it.
func (q *Queries) LockUserOwnedOrgs(ctx context.Context, userID uuid.UUID) ([]LockUserOwnedOrgsRow, error) {
	rows, err := q.db.Query(ctx, lockUserOwnedOrgs, userID)
	if err != nil {
		return nil, err
	}
	defer rows.Close()
	var items []LockUserOwnedOrgsRow
	for rows.Next() {
		var i LockUserOwnedOrgsRow
		if err := rows.Scan(&i.OrgID, &i.UserID); err != nil {
			return nil, err
		}
		items = append(items, i)
	}
	if err := rows.Err(); err != nil {
		return nil, err
	}
	return items, nil
}

const lookupLoginUser = `-- name: LookupLoginUser :one
SELECT u.id, u.login, m.role,
       (SELECT array_agg(tm.team_id ORDER BY tm.team_id) FROM team_member tm
        WHERE tm.org_id = m.org_id AND tm.user_id = u.id)::uuid[] AS team_ids
FROM users u
JOIN membership m ON m.user_id = u.id AND m.org_id = $1
WHERE u.login = $2
`

type LookupLoginUserParams struct {
	OrgID uuid.UUID
	Login string
}

type LookupLoginUserRow struct {
	ID      uuid.UUID
	Login   string
	Role    string
	TeamIds []uuid.UUID
}

// ponytail: the team sub-select runs with werbot.user_id unset (uuid.Nil: the
// tunnel's ReadInOrg has no user); stage 42 RLS on team_member must allow it.
func (q *Queries) LookupLoginUser(ctx context.Context, arg LookupLoginUserParams) (LookupLoginUserRow, error) {
	row := q.db.QueryRow(ctx, lookupLoginUser, arg.OrgID, arg.Login)
	var i LookupLoginUserRow
	err := row.Scan(
		&i.ID,
		&i.Login,
		&i.Role,
		&i.TeamIds,
	)
	return i, err
}

const lookupSSHKeyUser = `-- name: LookupSSHKeyUser :one
SELECT u.id, u.login, m.role,
       (SELECT array_agg(tm.team_id ORDER BY tm.team_id) FROM team_member tm
        WHERE tm.org_id = m.org_id AND tm.user_id = u.id)::uuid[] AS team_ids
FROM user_ssh_key k
JOIN users u ON u.id = k.user_id
JOIN membership m ON m.user_id = u.id AND m.org_id = $1
WHERE k.fingerprint_sha256 = $2
`

